package com.example.bdd;

import io.cucumber.java.en.Given;
import io.cucumber.java.en.Then;
import io.cucumber.java.en.When;
import static org.junit.jupiter.api.Assertions.assertEquals;

public class AccountStepDefinitions {
    private double balance;

    @Given("a user has an account balance of {double}")
    public void a_user_has_an_account_balance_of(double initialBalance) {
        this.balance = initialBalance;
    }

    @When("they withdraw {double}")
    public void they_withdraw(double amount) {
        this.balance -= amount;
    }

    @Then("the new balance should be {double}")
    public void the_new_balance_should_be(double expectedBalance) {
        assertEquals(expectedBalance, this.balance, 0.001);
    }
}
